/bin/bash -lc "python - <<'PY'
import json
p='run_trace/galaxy_tool_schema_005/build_response.json'
d=json.load(open(p))
# recursively find any object with name/path target, print local context as JSON

def walk(x,path=''):
    if isinstance(x,dict):
        if x.get('name') in ('extract_options','target','keep_regex') or x.get('path','').startswith('extract_options'):
            print(path, json.dumps(x,indent=2)[:5000])
        for k,v in x.items(): walk(v,path+'/'+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+'/'+str(i))
walk(d)
PY"

