/bin/bash -lc "python - <<'PY'
import json
p='run_trace/galaxy_tool_schema_006/build_response.json'
d=json.load(open(p))
def walk(x,path=''):
    if isinstance(x,dict):
        if x.get('name') in ('how','how_filter','filter_source') or x.get('path','').startswith('how'):
            print(path, json.dumps(x,indent=2)[:5000])
        for k,v in x.items(): walk(v,path+'/'+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+'/'+str(i))
walk(d)
PY"

