/bin/bash -lc "python - <<'PY'
import inspect
from bioblend.galaxy import GalaxyInstance
print(hasattr(GalaxyInstance,'unprivileged_tools'))
if hasattr(GalaxyInstance,'unprivileged_tools'):
 from bioblend.galaxy.unprivileged_tools import UnprivilegedToolClient
 print([x for x in dir(UnprivilegedToolClient) if 'tool' in x or 'run' in x or 'create' in x])
 for n in dir(UnprivilegedToolClient):
  if 'tool' in n or 'run' in n or 'create' in n:
   try: print(n,inspect.signature(getattr(UnprivilegedToolClient,n)))
   except: pass
PY"

